    id,
    stateDir,
    sessionRoot,
    healthUrl: options.healthUrl,
    schedule,
    dryRun: options.dryRun === true,
    targetPid: options.targetPid,
    relaunchCommand: options.relaunchCommand,
    callerPid: options.callerPid,
  };

