  let healthHost = '127.0.0.1';
  const healthUrl = String(payload.healthUrl ?? '');
  if (healthUrl !== '') {
    try {
      const url = new URL(healthUrl);
      healthHost = url.hostname;
      port = Number(url.port) || (url.protocol === 'https:' ? 443 : 80);
    } catch {
