    const child = spawn(argv[0], argv.slice(1), {
      detached: true,
      stdio: 'ignore',
      cwd: plan.workingDirectory,
      env: (() => {
        const env = { ...process.env };
        delete env.DSH_SESSION_ID;
        delete env.DSH_WEB_URL;
        delete env.DSH_SHELL;
